class PushBoxGame:
    """
    This class implements a functionality of a sokoban game, where the player needs to move boxes to designated targets in order to win.
    """

    def __init__(self, map):
        self.map = map
        self.player_row = 0
        self.player_col = 0
        self.targets = []
        self.boxes = []
        self.target_count = 0
        self.is_game_over = False
        self.init_game()

    def init_game(self):
        for row in range(len(self.map)):
            for col in range(len(self.map[row])):
                if self.map[row][col] == 'O':
                    self.player_row = row
                    self.player_col = col
                elif self.map[row][col] == 'G':
                    self.targets.append((row, col))
                elif self.map[row][col] == 'X':
                    self.boxes.append((row, col))
        self.target_count = len(self.targets)

    def check_win(self):
        for box in self.boxes:
            if box not in self.targets:
                return False
        self.is_game_over = True
        return self.is_game_over

    def move(self, direction):
        new_row = self.player_row
        new_col = self.player_col

        if direction == 'w' and self.map[new_row - 1][new_col] != '#':
            new_row -= 1
        elif direction == 's' and self.map[new_row + 1][new_col] != '#':
            new_row += 1
        elif direction == 'a' and self.map[new_row][new_col - 1] != '#':
            new_col -= 1
        elif direction == 'd' and self.map[new_row][new_col + 1] != '#':
            new_col += 1

        if (new_row, new_col) in self.boxes:
            box_index = self.boxes.index((new_row, new_col))
            new_box_row = new_row
            new_box_col = new_col

            if direction == 'w' and self.map[new_box_row - 1][new_box_col] != '#':
                new_box_row -= 1
            elif direction == 's' and self.map[new_box_row + 1][new_box_col] != '#':
                new_box_row += 1
            elif direction == 'a' and self.map[new_box_row][new_box_col - 1] != '#':
                new_box_col -= 1
            elif direction == 'd' and self.map[new_box_row][new_box_col + 1] != '#':
                new_box_col += 1

            if (new_box_row, new_box_col) in self.boxes or (new_box_row, new_box_col) in self.targets:
                return False

            self.boxes[box_index] = (new_box_row, new_box_col)
            self.boxes.append((new_row, new_col))
            self.boxes.remove((self.player_row, self.player_col))
            self.player_row = new_row
            self.player_col = new_col
        else:
            self.player_row = new_row
            self.player_col = new_col

        return self.check_win()

    def print_map(self):
        for row in range(len(self.map)):
            line = ""
            for col in range(len(self.map[row])):
                if (row, col) == (self.player_row, self.player_col):
                    line += "O"
                elif (row, col) in self.boxes:
                    line += "X"
                elif (row, col) in self.targets:
                    line += "G"
                else:
                    line += "#"
            print(line)
